        if vt == 10: return ('u64', struct.unpack('<Q', f.read(8))[0])
        if vt == 11: return ('i64', struct.unpack('<q', f.read(8))[0])
        if vt == 12: return ('f64', struct.unpack('<d', f.read(8))[0])
        return ('unknown', vt)

