        async_stream::stream! {
            // 1. 异步打开文件
            let mut file = match tokio::fs::File::open(file_path).await {
                Ok(f) => f,
                Err(e) =>{ 
                    yield Err(ServiceError::InvalidInput(e.to_string()));
                    return;
                }
            };
            
            // 2. 预分配缓冲区
            let mut buffer = vec![0u8; chunk_size];
            
            // 3. 核心循环：不断读取数据
            loop {
                // 异步地读取数据
                let bytes_read = match file.read_buf(&mut buffer).await {   
                    Ok(0) => 0,
                    Ok(n) => n,
                    Err(e) => {
                        yield Err(ServiceError::InvalidInput(e.to_string()));
                        return;
                    }
                };
                
              
