                Ok(f) => f,
                Err(e) =>{ 
                    yield Err(ServiceError::InvalidInput(e.to_string()));
                    return;
                }
            };
            
            // 2. 预分配缓冲区
            let mut buffer = vec![0u8; chunk_size];
            
