pub fn unicode_to_bytes() -> &'static HashMap<char, u8> {
    static BYTE_DECODER: OnceLock<HashMap<char, u8>> = OnceLock::new();
    BYTE_DECODER.get_or_init(|| bytes_to_unicode().iter().map(|(&k, &v)| (v, k)).collect())
}

