            } else {
                tracing::warn!("Failed to get client for server {}", server_id);
            }
        }
    }

    tracing::warn!("No external tool found, falling back to internal");
    let result = ToolRegistry::call_tool(&name, &args).await?;
    Ok(Json(result))
}

