///
/// A static reference to the byte-to-character mapping.
pub fn bytes_to_unicode() -> &'static HashMap<u8, char> {
    static BYTE_ENCODER: OnceLock<HashMap<u8, char>> = OnceLock::new();
    BYTE_ENCODER.get_or_init(|| {
