        assert_tokens_in_bounds(tokens, vocab_size);

        // Sanity check: token count should be reasonable
        // (at most 4 tokens per input byte is a very generous upper bound)
        debug_assert!(
            tokens.len() <= crate::MAX_OUTPUT_TOKENS,
