                    // Use word1.get() to safely slice, which handles UTF-8 boundaries
                    if let Some(s) = word1.get(i..j) {
                        if let Some(id) = vocab.get_token_id(s) {
                            out.push(id);
                            matched = true;
                            i = j; // next position
                            break;
                        }
