    let secret = get_jwt_secret();
    let expiration = (Utc::now() + chrono::Duration::hours(24)).timestamp() as usize;
    
    let claims = Claims { user_id, exp: expiration };
    encode(
        &Header::default(),
        &claims,
        &EncodingKey::from_secret(secret.as_ref()),
    )
}

