                        println!("Tokens (with BOS): {:?}", tokens_with_bos);
                    }

                    // Decode back
                    if let Ok(decoded) = tokenizer.decode(&tokens, false) {
                        println!("Decoded: {:?}", decoded);
                    }
                }
                Err(e) => println!("Encode error: {}", e),
            }
        }
