        .map_err(|_| ServiceError::InternalError)?;
    
    let mut redis_conn = get_redis_connection().await?;
    let _: () = redis_conn.set_ex(format!("refresh_token:{}", user.id), &refresh_token, 60 * 60 * 24 * 7).await
