    pub fn new(vocab: &Vocabulary) -> Self {
        let mut max_len = 0usize;
        for id in 0..(vocab.n_tokens() as u32) {
            if let Some(t) = vocab.get_token_text(id) {
                max_len = max_len.max(t.len());
            }
        }
        Self {
            max_token_len: max_len,
        }
    }

